328	// enrichImagesWithContentSize populates Size (content size) from docker image inspect.
329	// docker image inspect .Size gives the real content size (compressed layers in content store),
330	// while docker image ls .Size gives disk usage (unpacked layers on disk).
331	func enrichImagesWithContentSize(images []Image) {
332		if len(images) == 0 {
333			return
334		}
335	
336		// Collect all image IDs
337		ids := make([]string, 0, len(images))
338		for _, img := range images {
339			ids = append(ids, img.ID)
340		}
341	
342		// docker image inspect --format '{{.ID}} {{.Size}}' id1 id2 ...
343		args := append([]string{"image", "inspect", "--format", "{{.ID}}\t{{.Size}}"}, ids...)
344		cmd := exec.Command("docker", args...)
345		output, err := cmd.Output()
346		if err != nil {
347			return
348		}
349	
350		// Build lookup by short ID (strip "sha256:" prefix, keep first 12 chars)
351		lookup := make(map[string]int64)
352		for line := range strings.SplitSeq(strings.TrimSpace(string(output)), "\n") {
353			if line == "" {
354				continue
355			}
356			parts := strings.SplitN(line, "\t", 2)
357			if len(parts) < 2 {
358				continue
359			}
360			fullID := strings.TrimPrefix(parts[0], "sha256:")
361			shortID := fullID
362			if len(shortID) > 12 {
363				shortID = shortID[:12]
364			}
365			size, _ := strconv.ParseInt(parts[1], 10, 64)
366			lookup[shortID] = size
367		}
368	
369		for i := range images {
370			if size, ok := lookup[images[i].ID]; ok {
371				images[i].Size = size
372			}
373		}
