376	// enrichImagesWithDiskUsage populates UniqueSize and Containers from docker system df -v.
377	// Parses the raw text output because --format with -v does not expose per-image fields.
378	func enrichImagesWithDiskUsage(images []Image) {
379		cmd := exec.Command("docker", "system", "df", "-v")
380		output, err := cmd.Output()
381		if err != nil {
382			return
383		}
384	
385		type dfInfo struct {
386			UniqueSize int64
387			Containers int
388		}
389		lookup := make(map[string]dfInfo)
390	
391		lines := strings.Split(string(output), "\n")
392		inImages := false
393		// Column start positions derived from the header line
394		var tagPos, uniquePos, contPos int
395		headerFound := false
396	
397		for _, line := range lines {
398			trimmed := strings.TrimSpace(line)
399	
400			// Detect the Images section
401			if strings.HasPrefix(trimmed, "Images space usage:") {
402				inImages = true
403				continue
404			}
405			// End of Images section
406			if inImages && (strings.HasPrefix(trimmed, "Containers space usage:") ||
407				strings.HasPrefix(trimmed, "Local Volumes space usage:") ||
408				strings.HasPrefix(trimmed, "Build cache usage:")) {
409				break
410			}
411			if !inImages || trimmed == "" {
412				continue
413			}
414	
415			// Parse the header line to discover column positions
416			if strings.HasPrefix(trimmed, "REPOSITORY") {
417				tagPos = strings.Index(line, "TAG")
418				uniquePos = strings.Index(line, "UNIQUE SIZE")
419				contPos = strings.Index(line, "CONTAINERS")
420				headerFound = tagPos > 0 && uniquePos > 0 && contPos > 0
421				continue
422			}
423			if !headerFound {
424				continue
425			}
426	
427			// Extract fields using fixed column positions from the header
428			repo := strings.TrimSpace(safeSlice(line, 0, tagPos))
429			tag := strings.TrimSpace(safeSlice(line, tagPos, tagPos+20)) // TAG column is short
430			// Clean tag: take first word only (avoids bleeding into IMAGE ID)
431			if sp := strings.IndexByte(tag, ' '); sp > 0 {
432				tag = tag[:sp]
433			}
434			uniqueStr := strings.TrimSpace(safeSlice(line, uniquePos, contPos))
435			contStr := strings.TrimSpace(safeSlice(line, contPos, len(line)))
436			// Containers count is the first word of the remaining text
437			if sp := strings.IndexByte(contStr, ' '); sp > 0 {
438				contStr = contStr[:sp]
439			}
440	
441			if repo == "" || tag == "" {
442				continue
443			}
444	
445			key := repo + ":" + tag
446			containers, _ := strconv.Atoi(contStr)
447			lookup[key] = dfInfo{UniqueSize: parseSize(uniqueStr), Containers: containers}
448		}
449	
450		for i := range images {
451			key := images[i].Repository + ":" + images[i].Tag
452			if info, ok := lookup[key]; ok {
453				images[i].UniqueSize = info.UniqueSize
454				images[i].Containers = info.Containers
455			}
456		}
457	}
