482	// parseSize parses Docker human-readable sizes like "1.5GB", "256MB", "10.2kB" into bytes
483	func parseSize(s string) int64 {
484		s = strings.TrimSpace(s)
485		if s == "" {
486			return 0
487		}
488	
489		multipliers := []struct {
490			suffix string
491			mult   float64
492		}{
493			{"GB", 1e9},
494			{"MB", 1e6},
495			{"kB", 1e3},
496			{"B", 1},
497		}
498	
499		for _, m := range multipliers {
500			if numStr, ok := strings.CutSuffix(s, m.suffix); ok {
501				num, err := strconv.ParseFloat(numStr, 64)
502				if err != nil {
503					return 0
504				}
505				return int64(num * m.mult)
506			}
507		}
508		return 0
509	}
