552	// FetchContainerStats queries Docker for container status counts.
553	// Uses the docker CLI to avoid importing the heavy Docker SDK.
554	func FetchContainerStats() ContainerStats {
555		stats := ContainerStats{}
556	
557		// Check if docker is available
558		if _, err := exec.LookPath("docker"); err != nil {
559			return stats
560		}
561	
562		// Get all containers with their status
563		cmd := exec.Command("docker", "ps", "-a", "--format", "{{.State}}")
564		output, err := cmd.Output()
565		if err != nil {
566			return stats
