569		stats.Available = true
570	
571		for line := range strings.SplitSeq(strings.TrimSpace(string(output)), "\n") {
572			if line == "" {
573				continue
574			}
575			switch line {
576			case "running":
577				stats.Running++
578			case "paused":
579				stats.Paused++
580			default:
581				// exited, created, restarting, removing, dead
582				stats.Stopped++
583			}
584		}
585	
586		return stats
587	}
