742	// buildLaunchArgs constructs the docker run argument list for the given options.
743	func buildLaunchArgs(opts ContainerLaunchOptions) []string {
744		args := []string{"run"}
745		if opts.Remove {
746			args = append(args, "--rm")
747		}
748		if opts.Detach {
749			args = append(args, "-d")
750		}
751		if opts.Interactive {
752			args = append(args, "-i")
753		}
754		if opts.TTY {
755			args = append(args, "-t")
756		}
757		if opts.Name != "" {
758			args = append(args, "--name", opts.Name)
759		}
760		if opts.Entrypoint != "" {
761			args = append(args, "--entrypoint", opts.Entrypoint)
762		}
763		for _, p := range opts.Ports {
764			if p != "" {
765				args = append(args, "-p", p)
766			}
767		}
768		for _, e := range opts.Env {
769			if e != "" {
770				args = append(args, "-e", e)
771			}
772		}
773		for _, v := range opts.Volumes {
774			if v != "" {
775				args = append(args, "-v", v)
776			}
777		}
778		if opts.Network != "" {
779			args = append(args, "--network", opts.Network)
780		}
781		if opts.User != "" {
782			args = append(args, "--user", opts.User)
783		}
784		args = append(args, opts.Image)
