850	// dockerHubKeys lists all keys Docker uses for Docker Hub in ~/.docker/config.json.
851	// `docker login docker.io` stores credentials under "https://index.docker.io/v1/".
852	var dockerHubKeys = []string{
853		"docker.io",
854		"registry-1.docker.io",
855		"https://index.docker.io/v1/",
856		"https://index.docker.io/v1",
857		"https://registry-1.docker.io",
858	}
