860	// registryCandidates returns all URL variants to look up in ~/.docker/config.json.
861	func registryCandidates(registryURL string) []string {
862		base := strings.TrimSuffix(registryURL, "/")
863	
864		// Check if this URL is any known Docker Hub alias; if so, return the full set.
865		for _, alias := range dockerHubKeys {
866			if strings.EqualFold(base, strings.TrimSuffix(alias, "/")) {
867				return dockerHubKeys
868			}
869		}
870	
871		// Generic: bare hostname, https://, http:// variants.
872		candidates := []string{base}
873		if strings.HasPrefix(base, "https://") {
874			candidates = append(candidates, strings.TrimPrefix(base, "https://"))
875		} else if strings.HasPrefix(base, "http://") {
876			candidates = append(candidates, strings.TrimPrefix(base, "http://"))
877		} else {
878			candidates = append(candidates, "https://"+base, "http://"+base)
879		}
880		return candidates
881	}
