895			Auths map[string]json.RawMessage `json:"auths"`
896		}
897		if err := json.Unmarshal(data, &cfg); err != nil {
898			return false
899		}
900		for _, c := range registryCandidates(registryURL) {
901			if _, ok := cfg.Auths[c]; ok {
902				return true
903			}
904		}
905		return false
906	}
