908	// RegistryLogout removes stored credentials for a Docker/OCI registry.
909	// It runs `docker logout` (cleans system credential stores) then directly
910	// removes all matching keys from ~/.docker/config.json to handle cases where
911	// docker logout leaves behind alias entries (e.g. docker.io vs https://index.docker.io/v1/).
912	func RegistryLogout(registryURL string) error {
913		if _, err := exec.LookPath("docker"); err != nil {
914			return fmt.Errorf("docker not found: %w", err)
915		}
916		cmd := exec.Command("docker", "logout", registryURL)
917		if output, err := cmd.CombinedOutput(); err != nil {
918			return fmt.Errorf("docker logout failed: %s", strings.TrimSpace(string(output)))
919		}
920		// Also remove all matching alias keys directly from config.json.
921		_ = removeFromDockerConfig(registryURL)
922		return nil
923	}
