925	// removeFromDockerConfig removes all URL variants of registryURL from the auths
926	// section of ~/.docker/config.json. Errors are non-fatal (best effort).
927	func removeFromDockerConfig(registryURL string) error {
928		home, err := os.UserHomeDir()
929		if err != nil {
930			return err
931		}
932		configPath := filepath.Join(home, ".docker", "config.json")
933		data, err := os.ReadFile(configPath)
934		if err != nil {
935			return err
936		}
937	
938		var raw map[string]json.RawMessage
939		if err := json.Unmarshal(data, &raw); err != nil {
940			return err
941		}
942		authsRaw, ok := raw["auths"]
943		if !ok {
944			return nil
945		}
946		var auths map[string]json.RawMessage
947		if err := json.Unmarshal(authsRaw, &auths); err != nil {
948			return err
949		}
950	
951		changed := false
952		for _, candidate := range registryCandidates(registryURL) {
953			if _, exists := auths[candidate]; exists {
954				delete(auths, candidate)
955				changed = true
956			}
957		}
958		if !changed {
959			return nil
960		}
961	
962		updated, err := json.Marshal(auths)
963		if err != nil {
964			return err
965		}
966		raw["auths"] = updated
967		out, err := json.MarshalIndent(raw, "", "\t")
968		if err != nil {
969			return err
970		}
971		return os.WriteFile(configPath, out, 0600)
972	}
