974	// GetStoredCreds retrieves Docker credentials for registryURL from
975	// ~/.docker/config.json. It tries the per-registry credential helper
976	// (credHelpers), then the global credsStore, and finally falls back to the
977	// inline base64-encoded auth field. Returns ok=false when no credentials are
978	// found.
979	func GetStoredCreds(registryURL string) (username, password string, ok bool) {
980		home, err := os.UserHomeDir()
981		if err != nil {
982			return "", "", false
983		}
984		data, err := os.ReadFile(filepath.Join(home, ".docker", "config.json"))
985		if err != nil {
986			return "", "", false
987		}
988	
989		var cfg struct {
990			Auths map[string]struct {
991				Auth string `json:"auth"`
992			} `json:"auths"`
993			CredsStore  string            `json:"credsStore"`
994			CredHelpers map[string]string `json:"credHelpers"`
995		}
996		if err := json.Unmarshal(data, &cfg); err != nil {
997			return "", "", false
998		}
999	
1000		// Normalise the URL to a bare hostname for helper lookups.
1001		hostname := strings.TrimSuffix(registryURL, "/")
1002		for _, prefix := range []string{"https://", "http://"} {
1003			hostname = strings.TrimPrefix(hostname, prefix)
1004		}
1005	
1006		helper := cfg.CredHelpers[hostname]
1007		if helper == "" {
1008			helper = cfg.CredsStore
1009		}
1010		if helper != "" {
1011			if u, p, ok := getCredsFromHelper(helper, hostname); ok {
1012				return u, p, true
1013			}
1014		}
1015	
1016		for _, candidate := range registryCandidates(registryURL) {
1017			if entry, ok := cfg.Auths[candidate]; ok && entry.Auth != "" {
1018				decoded, err := base64.StdEncoding.DecodeString(entry.Auth)
1019				if err != nil {
1020					continue
1021				}
1022				if idx := strings.IndexByte(string(decoded), ':'); idx >= 0 {
1023					return string(decoded[:idx]), string(decoded[idx+1:]), true
1024				}
1025			}
1026		}
1027		return "", "", false
1028	}
1029	
1030	// getCredsFromHelper calls `docker-credential-<helper> get` and parses the JSON response.
1031	func getCredsFromHelper(helper, serverURL string) (username, password string, ok bool) {
1032		cmd := exec.Command("docker-credential-"+helper, "get") //nolint:gosec
1033		cmd.Stdin = strings.NewReader(serverURL)
1034		out, err := cmd.Output()
1035		if err != nil {
1036			return "", "", false
1037		}
1038		var result struct {
1039			Username string `json:"Username"`
1040			Secret   string `json:"Secret"`
1041		}
1042		if err := json.Unmarshal(out, &result); err != nil {
1043			return "", "", false
1044		}
1045		if result.Secret == "" {
1046			return "", "", false
1047		}
1048		return result.Username, result.Secret, true
1049	}
