1057	// ApplyAliases replaces registry URL prefixes in an image name with their configured alias.
1058	// Example: URL="gitlab.com/my-group", Alias="gl" turns
1059	// "gitlab.com/my-group/my-image:1.0" into "gl/my-image:1.0".
1060	func ApplyAliases(imageName string, aliases []RegistryAlias) string {
