1065			prefix := strings.TrimSuffix(a.URL, "/") + "/"
1066			if strings.HasPrefix(imageName, prefix) {
1067				return a.Alias + "/" + strings.TrimPrefix(imageName, prefix)
1068			}
1069		}
1070		return imageName
1071	}
