1104			return nil, fmt.Errorf("failed to parse network inspect output: %w", err)
1105		}
1106		if len(results) == 0 {
1107			return nil, nil
1108		}
1109		var containers []NetworkContainer
1110		for _, c := range results[0].Containers {
1111			ip := c.IPv4Address
1112			if idx := strings.Index(ip, "/"); idx > 0 {
1113				ip = ip[:idx]
1114			}
1115			containers = append(containers, NetworkContainer{
1116				Name:       c.Name,
1117				IPv4:       ip,
1118				MacAddress: c.MacAddress,
1119			})
1120		}
1121		sort.Slice(containers, func(i, j int) bool {
1122			return containers[i].Name < containers[j].Name
1123		})
