package docker

import (
	"strconv"
	"strings"
)

// Image represents a Docker image with its metadata
type Image struct {
	ID         string
	Repository string
	Tag        string
	Size       int64 // Content size (virtual size) in bytes
	UniqueSize int64 // Disk usage (unique layers) in bytes
	Containers int
	CreatedAt  string
}

// Name returns "repository:tag", omitting the tag suffix when tag is "<none>".
func (img Image) Name() string {
	if img.Tag == "" || img.Tag == "<none>" {
		return img.Repository
	}
	return img.Repository + ":" + img.Tag
}

// ScanTarget returns the best identifier to pass to Trivy for a local scan.
// When an image has no tag, the short ID is used so Trivy resolves it locally
// instead of trying to pull "repository:latest" from a registry.
func (img Image) ScanTarget() string {
	if img.Tag == "" || img.Tag == "<none>" {
		return img.ID
	}
	return img.Name()
}

// ListImages returns a list of local Docker images
func ListImages() ([]Image, error) {
	if err := requireDocker(); err != nil {
		return nil, err
	}

	// {{.Size}} from docker image ls gives disk usage (not content size)
	output, err := dockerOutput("image", "ls", "--format",
		"{{.ID}}\t{{.Repository}}\t{{.Tag}}\t{{.Size}}\t{{.CreatedAt}}")
	if err != nil {
		return nil, wrapErr("docker image ls", err)
	}

	var images []Image
	for _, line := range splitLines(output) {
		parts := strings.SplitN(line, "\t", 5)
		if len(parts) < 3 {
			continue
		}
		img := Image{
			ID:         parts[0],
			Repository: parts[1],
			Tag:        parts[2],
		}
		if len(parts) > 3 {
			// docker image ls {{.Size}} = disk usage
			img.UniqueSize = parseSize(parts[3])
		}
		if len(parts) > 4 {
			img.CreatedAt = parts[4]
		}
		images = append(images, img)
	}

	// Enrich with content size from docker image inspect and
	// more precise disk usage from docker system df -v
	enrichImagesWithDiskUsage(images)
	enrichImagesWithContentSize(images)

	return images, nil
}

// enrichImagesWithContentSize populates Size (content size) from docker image inspect.
// docker image inspect .Size gives the real content size (compressed layers in content store),
// while docker image ls .Size gives disk usage (unpacked layers on disk).
func enrichImagesWithContentSize(images []Image) {
	if len(images) == 0 {
		return
	}

	ids := make([]string, 0, len(images))
	for _, img := range images {
		ids = append(ids, img.ID)
	}

	args := append([]string{"image", "inspect", "--format", "{{.ID}}\t{{.Size}}"}, ids...)
	output, err := dockerOutput(args...)
	if err != nil {
		return
	}

	// Build lookup by short ID (strip "sha256:" prefix, keep first 12 chars)
	lookup := make(map[string]int64)
	for _, line := range splitLines(output) {
		parts := strings.SplitN(line, "\t", 2)
		if len(parts) < 2 {
			continue
		}
		shortID := strings.TrimPrefix(parts[0], "sha256:")
		if len(shortID) > 12 {
			shortID = shortID[:12]
		}
		size, _ := strconv.ParseInt(parts[1], 10, 64)
		lookup[shortID] = size
	}

	for i := range images {
		if size, ok := lookup[images[i].ID]; ok {
			images[i].Size = size
		}
	}
}

// dfInfo holds the per-image figures scraped from `docker system df -v`.
type dfInfo struct {
	UniqueSize int64
	Containers int
}

// enrichImagesWithDiskUsage populates UniqueSize and Containers from docker system df -v.
// Parses the raw text output because --format with -v does not expose per-image fields.
func enrichImagesWithDiskUsage(images []Image) {
	output, err := dockerOutput("system", "df", "-v")
	if err != nil {
		return
	}

	lookup := parseImagesDiskUsage(string(output))
	for i := range images {
		key := images[i].Repository + ":" + images[i].Tag
		if info, ok := lookup[key]; ok {
			images[i].UniqueSize = info.UniqueSize
			images[i].Containers = info.Containers
		}
	}
}

// parseImagesDiskUsage extracts the "Images space usage" table from
// `docker system df -v`, keyed by "repository:tag".
//
// The table is fixed-width rather than delimited, so column offsets are taken
// from the header line and every row is sliced at those offsets.
func parseImagesDiskUsage(output string) map[string]dfInfo {
	lookup := make(map[string]dfInfo)

	inImages := false
	headerFound := false
	var tagPos, uniquePos, contPos int

	for _, line := range strings.Split(output, "\n") {
		trimmed := strings.TrimSpace(line)

		if strings.HasPrefix(trimmed, "Images space usage:") {
			inImages = true
			continue
		}
		if inImages && (strings.HasPrefix(trimmed, "Containers space usage:") ||
			strings.HasPrefix(trimmed, "Local Volumes space usage:") ||
			strings.HasPrefix(trimmed, "Build cache usage:")) {
			break
		}
		if !inImages || trimmed == "" {
			continue
		}

		if strings.HasPrefix(trimmed, "REPOSITORY") {
			tagPos = strings.Index(line, "TAG")
			uniquePos = strings.Index(line, "UNIQUE SIZE")
			contPos = strings.Index(line, "CONTAINERS")
			headerFound = tagPos > 0 && uniquePos > 0 && contPos > 0
			continue
		}
		if !headerFound {
			continue
		}

		repo := strings.TrimSpace(safeSlice(line, 0, tagPos))
		// The TAG column is short; take the first word so it cannot bleed into IMAGE ID.
		tag := firstWord(strings.TrimSpace(safeSlice(line, tagPos, tagPos+tagColumnWidth)))
		uniqueStr := strings.TrimSpace(safeSlice(line, uniquePos, contPos))
		contStr := firstWord(strings.TrimSpace(safeSlice(line, contPos, len(line))))

		if repo == "" || tag == "" {
			continue
		}
		containers, _ := strconv.Atoi(contStr)
		lookup[repo+":"+tag] = dfInfo{UniqueSize: parseSize(uniqueStr), Containers: containers}
	}

	return lookup
}

// tagColumnWidth is how far past the TAG offset a tag may run before the next
// column starts. Docker does not pad this column to a documented width, so the
// value is a heuristic wide enough for realistic tags.
const tagColumnWidth = 20

// firstWord returns s up to its first space.
func firstWord(s string) string {
	if sp := strings.IndexByte(s, ' '); sp > 0 {
		return s[:sp]
	}
	return s
}

// RemoveImage removes a Docker image by ID. If force is true, uses -f flag.
func RemoveImage(id string, force bool) error {
	args := []string{"rmi", id}
	if force {
		args = []string{"rmi", "-f", id}
	}
	return mutate("docker rmi", args...)
}

// PruneImages removes all dangling (unused) images and returns the output
func PruneImages() (string, error) {
	return prune("docker image prune", "image", "prune", "-f")
}

// PullImage pulls a Docker image from a registry.
func PullImage(imageName string) error {
	if err := requireDocker(); err != nil {
		return err
	}
	return mutate("docker pull", "pull", imageName)
}

// GetImageExposedPorts returns the container port specs declared by EXPOSE in an image.
// Each entry uses the "port/protocol" format, e.g. "80/tcp" or "53/udp".
func GetImageExposedPorts(imageName string) ([]string, error) {
	if err := requireDocker(); err != nil {
		return nil, err
	}
	output, err := dockerOutput("image", "inspect", "--format", "{{json .Config.ExposedPorts}}", imageName)
	if err != nil {
		return nil, wrapErr("docker image inspect", err)
	}
	return parseExposedPorts(string(output)), nil
}

// parseExposedPorts pulls the port specs out of an ExposedPorts JSON object,
// which looks like {"80/tcp":{},"443/tcp":{}}.
func parseExposedPorts(raw string) []string {
	raw = strings.TrimSpace(raw)
	if raw == "null" || raw == "" {
		return nil
	}
	raw = strings.TrimSuffix(strings.TrimPrefix(raw, "{"), "}")
	if raw == "" {
		return nil
	}

	var ports []string
	for part := range strings.SplitSeq(raw, ",") {
		part = strings.TrimSpace(part)
		if idx := strings.Index(part, ":"); idx > 0 {
			if portSpec := strings.Trim(part[:idx], "\""); portSpec != "" {
				ports = append(ports, portSpec)
			}
		}
	}
	return ports
}

package docker

import (
	"strconv"
	"strings"
)

// safeSlice returns s[start:end] clamped to valid bounds
func safeSlice(s string, start, end int) string {
	if start < 0 {
		start = 0
	}
	if start >= len(s) {
		return ""
	}
	if end > len(s) {
		end = len(s)
	}
	return s[start:end]
}

// parseNetIO parses Docker NetIO string "1.2kB / 3.4kB" into received and transmitted bytes
func parseNetIO(netIO string) (rx, tx int64) {
	parts := strings.SplitN(netIO, "/", 2)
	if len(parts) != 2 {
		return 0, 0
	}
	return parseSize(strings.TrimSpace(parts[0])), parseSize(strings.TrimSpace(parts[1]))
}

// parseSize parses Docker human-readable sizes like "1.5GB", "256MB", "10.2kB" into bytes
func parseSize(s string) int64 {
	s = strings.TrimSpace(s)
	if s == "" {
		return 0
	}

	multipliers := []struct {
		suffix string
		mult   float64
	}{
		{"GB", 1e9},
		{"MB", 1e6},
		{"kB", 1e3},
		{"B", 1},
	}

	for _, m := range multipliers {
		if numStr, ok := strings.CutSuffix(s, m.suffix); ok {
			num, err := strconv.ParseFloat(numStr, 64)
			if err != nil {
				return 0
			}
			return int64(num * m.mult)
		}
	}
	return 0
}

package docker

import (
	"strconv"
	"strings"
)

// OCIStats contains OCI resource counts and disk usage
type OCIStats struct {
	Available       bool
	ImagesCount     int
	ImagesSize      string
	ContainersCount int
	ContainersSize  string
	VolumesCount    int
	VolumesSize     string
}

// FetchOCIStats returns OCI resource counts and disk usage via docker system df
func FetchOCIStats() OCIStats {
	stats := OCIStats{}

	if runner.LookPath() != nil {
		return stats
	}

	output, err := dockerOutput("system", "df", "--format", "{{.Type}}\t{{.TotalCount}}\t{{.Size}}")
	if err != nil {
		return stats
	}

	stats.Available = true

	for _, line := range splitLines(output) {
		parts := strings.SplitN(line, "\t", 3)
		if len(parts) < 3 {
			continue
		}
		count, _ := strconv.Atoi(parts[1])
		size := parts[2]

		switch parts[0] {
		case "Images":
			stats.ImagesCount = count
			stats.ImagesSize = size
		case "Containers":
			stats.ContainersCount = count
			stats.ContainersSize = size
		case "Local Volumes":
			stats.VolumesCount = count
			stats.VolumesSize = size
		}
	}

	return stats
}

package docker

import "strings"

// Volume represents a Docker volume
type Volume struct {
	Name       string
	Driver     string
	Mountpoint string
	Created    string
}

// ListVolumes returns a list of Docker volumes
func ListVolumes() ([]Volume, error) {
	if err := requireDocker(); err != nil {
		return nil, err
	}
	output, err := dockerOutput("volume", "ls", "--format", "{{.Name}}\t{{.Driver}}\t{{.Mountpoint}}")
	if err != nil {
		return nil, wrapErr("docker volume ls", err)
	}

	var volumes []Volume
	for _, line := range splitLines(output) {
		parts := strings.SplitN(line, "\t", 3)
		if len(parts) < 2 {
			continue
		}
		v := Volume{Name: parts[0], Driver: parts[1]}
		if len(parts) > 2 {
			v.Mountpoint = parts[2]
		}
		volumes = append(volumes, v)
	}
	return volumes, nil
}

// CreateVolume creates a Docker volume with the given name and optional driver
func CreateVolume(name, driver string) error {
	args := []string{"volume", "create"}
	if driver != "" {
		args = append(args, "--driver", driver)
	}
	args = append(args, name)
	return mutate("docker volume create", args...)
}

// RemoveVolume removes a Docker volume by name
func RemoveVolume(name string) error {
	return mutate("docker volume rm", "volume", "rm", name)
}

// PruneVolumes removes all unused Docker volumes
func PruneVolumes() (string, error) {
	return prune("docker volume prune", "volume", "prune", "-f")
}

// Docker network resources: the `docker network` subcommand family.
//
// Not to be confused with ports.go, which reports the host's own listening
// sockets by running `ss` inside a --net=host container.
package docker

import (
	"encoding/json"
	"sort"
	"strings"
)

// Network represents a Docker network
type Network struct {
	ID      string
	Name    string
	Driver  string
	Scope   string
	Created string
}

// ListNetworks returns a list of Docker networks
func ListNetworks() ([]Network, error) {
	if err := requireDocker(); err != nil {
		return nil, err
	}
	output, err := dockerOutput("network", "ls", "--format",
		"{{.ID}}\t{{.Name}}\t{{.Driver}}\t{{.Scope}}\t{{.CreatedAt}}")
	if err != nil {
		return nil, wrapErr("docker network ls", err)
	}

	var networks []Network
	for _, line := range splitLines(output) {
		parts := strings.SplitN(line, "\t", 5)
		if len(parts) < 4 {
			continue
		}
		n := Network{ID: parts[0], Name: parts[1], Driver: parts[2], Scope: parts[3]}
		if len(parts) > 4 {
			n.Created = parts[4]
		}
		networks = append(networks, n)
	}
	return networks, nil
}

// CreateNetwork creates a Docker network with the given name and driver
func CreateNetwork(name, driver string) error {
	if driver == "" {
		driver = "bridge"
	}
	return mutate("docker network create", "network", "create", "--driver", driver, name)
}

// RemoveNetwork removes a Docker network by ID or name
func RemoveNetwork(id string) error {
	return mutate("docker network rm", "network", "rm", id)
}

// PruneNetworks removes all unused Docker networks
func PruneNetworks() (string, error) {
	return prune("docker network prune", "network", "prune", "-f")
}

// NetworkContainer represents a container connected to a Docker network
type NetworkContainer struct {
	Name       string
	IPv4       string
	MacAddress string
}

// networkInspectContainer is used for JSON parsing of docker network inspect output
type networkInspectContainer struct {
	Name        string `json:"Name"`
	MacAddress  string `json:"MacAddress"`
	IPv4Address string `json:"IPv4Address"`
}

// networkInspectResult is the top-level JSON structure from docker network inspect
type networkInspectResult struct {
	Containers map[string]networkInspectContainer `json:"Containers"`
}

// InspectNetwork returns the containers connected to a Docker network by ID or name.
func InspectNetwork(id string) ([]NetworkContainer, error) {
	if err := requireDocker(); err != nil {
		return nil, err
	}
	output, err := dockerOutput("network", "inspect", id)
	if err != nil {
		return nil, wrapErr("docker network inspect", err)
	}
	return parseNetworkInspect(output)
}

// parseNetworkInspect turns `docker network inspect` JSON into the connected
// container list, sorted by name so the table does not reshuffle between polls.
func parseNetworkInspect(output []byte) ([]NetworkContainer, error) {
	var results []networkInspectResult
	if err := json.Unmarshal(output, &results); err != nil {
		return nil, wrapErr("failed to parse network inspect output", err)
	}
	if len(results) == 0 {
		return nil, nil
	}

	var containers []NetworkContainer
	for _, c := range results[0].Containers {
		// IPv4Address carries a CIDR suffix ("172.17.0.2/16"); drop the mask.
		ip := c.IPv4Address
		if idx := strings.Index(ip, "/"); idx > 0 {
			ip = ip[:idx]
		}
		containers = append(containers, NetworkContainer{
			Name:       c.Name,
			IPv4:       ip,
			MacAddress: c.MacAddress,
		})
	}
	sort.Slice(containers, func(i, j int) bool {
		return containers[i].Name < containers[j].Name
	})
	return containers, nil
}

// RunDiagnosticContainer runs a command in an ephemeral container attached to a Docker network.
// The image must include ping, curl, and nc (netcat). Container is removed after execution (--rm).
func RunDiagnosticContainer(networkID, image string, command []string) (string, error) {
	if err := requireDocker(); err != nil {
		return "", err
	}
	args := append([]string{"run", "--rm", "--network", networkID, image}, command...)
	output, err := dockerCombined(args...)
	out := strings.TrimSpace(string(output))
	if err != nil {
		return out, wrapErr("diagnostic command", err)
	}
	return out, nil
}

