// argsFor returns the arguments of the first invocation whose subcommand matches.
func (s *stubRunner) argsFor(subcommand string) []string {
	for _, c := range s.calls {
		if len(c.Args) > 0 && c.Args[0] == subcommand {
			return c.Args
		}
	}
	return nil
}

