80	// InitializeProjectWithFiles creates an initial commit with the given files
81	func InitializeProjectWithFiles(c *gitlabclient.Client, projectID int, files []CommitAction) error {
82		actions := make([]*gitlabclient.CommitActionOptions, len(files))
83		for i, f := range files {
84			actions[i] = &gitlabclient.CommitActionOptions{
85				Action:   gitlabclient.Ptr(gitlabclient.FileActionValue(f.Action)),
86				FilePath: gitlabclient.Ptr(f.FilePath),
87				Content:  gitlabclient.Ptr(f.Content),
88			}
89		}
90	
91		opts := &gitlabclient.CreateCommitOptions{
92			Branch:        gitlabclient.Ptr("main"),
93			CommitMessage: gitlabclient.Ptr("Initial commit from template"),
94			Actions:       actions,
95		}
96	
97		_, _, err := c.Commits.CreateCommit(projectID, opts, gitlabclient.WithContext(context.Background()))
98		return err
99	}
