101	// DeleteGroup deletes a GitLab group and all its contents (subgroups, projects)
102	// If permanentlyRemove is true, the group is deleted immediately without a grace period.
103	// GitLab requires a two-step process for immediate deletion:
104	// 1. First mark for deletion (schedule) - GitLab renames the group with suffix
105	// 2. Then permanently remove using the new path with deletion suffix
106	func DeleteGroup(c *gitlabclient.Client, groupID int, fullPath string, permanentlyRemove bool) error {
107		if !permanentlyRemove {
108			// Simple deletion - just schedule for deletion
109			_, err := c.Groups.DeleteGroup(groupID, nil)
110			return err
111		}
112	
113		// Step 1: Mark for deletion (schedule)
114		// GitLab will rename the group to "{path}-deletion_scheduled-{id}"
115		_, err := c.Groups.DeleteGroup(groupID, nil)
116		if err != nil {
117			return err
118		}
119	
120		// Step 2: Permanently remove using the renamed path
121		// GitLab renames groups pending deletion to: {original_path}-deletion_scheduled-{id}
122		deletionPath := fmt.Sprintf("%s-deletion_scheduled-%d", fullPath, groupID)
123	
124		opts := &gitlabclient.DeleteGroupOptions{
125			PermanentlyRemove: gitlabclient.Ptr(true),
126			FullPath:          gitlabclient.Ptr(deletionPath),
127		}
128		// Use the deletion path as group identifier since the group was renamed
129		_, err = c.Groups.DeleteGroup(deletionPath, opts)
130		if err != nil {
131			return err
132		}
133	
134		// Small delay to allow GitLab to propagate the deletion
135		time.Sleep(500 * time.Millisecond)
136		return nil
137	}
138	
139	// DeleteProject deletes a GitLab project
140	// If permanentlyRemove is true, the project is deleted immediately without a grace period.
141	// GitLab requires a two-step process for immediate deletion:
142	// 1. First mark for deletion (schedule) - GitLab renames the project with suffix
143	// 2. Then permanently remove using the new path with deletion suffix
144	func DeleteProject(c *gitlabclient.Client, projectID int, fullPath string, permanentlyRemove bool) error {
145		if !permanentlyRemove {
146			_, err := c.Projects.DeleteProject(projectID, nil)
147			return err
148		}
149	
150		// Step 1: Mark for deletion (schedule)
151		// GitLab will rename the project to "{path}-deletion_scheduled-{id}"
152		_, err := c.Projects.DeleteProject(projectID, nil)
153		if err != nil {
154			return err
155		}
156	
157		// Step 2: Permanently remove using the renamed path
158		// GitLab renames projects pending deletion to: {original_path}-deletion_scheduled-{id}
159		deletionPath := fmt.Sprintf("%s-deletion_scheduled-%d", fullPath, projectID)
160	
161		opts := &gitlabclient.DeleteProjectOptions{
162			PermanentlyRemove: gitlabclient.Ptr(true),
163			FullPath:          gitlabclient.Ptr(deletionPath),
164		}
165		_, err = c.Projects.DeleteProject(deletionPath, opts)
166		if err != nil {
167			return err
168		}
169	
170		time.Sleep(500 * time.Millisecond)
171		return nil
172	}
