28	// Authenticate authentifie avec GitLab et sauvegarde les credentials
29	func (a *Auth) Authenticate(url, token string, saveCredentials bool) (*AuthResult, error) {
30		// Créer le client
31		c, err := NewClient(url, token)
32		if err != nil {
33			return nil, fmt.Errorf("failed to create client: %w", err)
34		}
