43			Client: c,
44			User:   user,
45		}
46	
47		// Sauvegarder les credentials si demandé
48		if saveCredentials && a.storage != nil {
49			if err := a.storage.Save(url, token); err != nil {
50				// Ne pas échouer l'authentification, mais avertir l'utilisateur
51				result.SaveWarning = fmt.Sprintf("Credentials not saved to Git Credential Manager: %v. Token will only be saved to config file if selected.", err)
